/** Announces that the kit is ready. Loaded last. */
(function (UC) {
  "use strict";
  if (UC.__duplicate) {
    console.warn("[uc-kit] uc-kit.js was loaded more than once; the extra copy was ignored.");
    return;
  }

  /** Longest wait for the web fonts and the page's modules before the page is shown anyway (first visit, slow network). */
  const FONT_WAIT_MS = 300;

  /**
   * Resolves once the page's body and code fonts are ready. The families are
   * read from the page, so a theme that changes --uc-font-sans or
   * --uc-font-mono waits for its own fonts (or for none, with system fonts).
   */
  function fontsReady() {
    if (!document.fonts || !document.fonts.load) return Promise.resolve();
    const root = getComputedStyle(document.documentElement);
    const families = [getComputedStyle(document.body).fontFamily, root.getPropertyValue("--uc-font-mono")]
      .map((family) => family.trim())
      .filter(Boolean);
    return Promise.all(families.map((family) => document.fonts.load(`1em ${family}`).catch(() => null)));
  }

  /**
   * The themes of course.js (core/themes.js) and the layout style sheets
   * (core/layouts.js), then the fonts they ask for, and
   * the modules the page needs (core/modules.js, e.g. uc-grading.js), under
   * one FONT_WAIT_MS cap, so a lazily loaded block is drawn before the
   * page shows on a fast or cached load (docs/architecture/grading-api.md 2.2).
   */
  function pageReady() {
    const timeout = new Promise((resolve) => setTimeout(resolve, FONT_WAIT_MS));
    return Promise.race([Promise.all([UC.internal.layoutsReady().then(fontsReady), UC.internal.modulesReady()]), timeout]);
  }

  function ready() {
    document.documentElement.classList.add("uc-ready");
    document.dispatchEvent(new CustomEvent("uc:ready", { detail: { version: UC.version } }));
    // uc-page stays hidden until this class is set (see uc-page.css).
    pageReady().then(() => {
      document.documentElement.classList.add("uc-visible");
      // The browser jumped to #hash while the page was hidden: jump again (core/anchors.js).
      requestAnimationFrame(UC.internal.anchors.revisitHash);
    });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", ready);
  else ready();
})(window.UC);